var g = Graphics.createArrayBuffer(128,32,8);
g.dump = _=>{
  var s = "";
  var b = new Uint8Array(g.buffer);
  var n = 0;
  var width = g.swapped ? g.getHeight() : g.getWidth();
  var height = g.swapped ? g.getWidth() : g.getHeight();
  for (var y=0;y<height;y++) {
    s+="\n";
    for (var x=0;x<width;x++)
      s+=".#"[b[n++]?1:0];
  }
  return s;
}
g.print = _=>{
  print("`"+g.dump()+"`");
}
var ok = true;
function SHOULD_BE(a) {
  var b = g.dump();
  if (a!=b) {
    console.log("GOT :"+b+"\nSHOULD BE:"+a+"\n================");
    ok = false;
  }
}

Graphics.prototype.setFontOpenSans = function() {
  // Actual height 15 (14 - 0)
  // 1 BPP
  return this.setFontCustom(
    atob(''),
    32,
    atob("BAQGCwkODAMFBgkKBAUEBgoGCgkKCQoJCgkEBAoKCQcOCwsLDAkJDAsEBAsJDgsNCg0LCQoLChAKCgkGBgY="),
    16|65536
  );
}

// left align
